 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 3 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            while q:
                y,x = q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == 3 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            boxes.append((min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    centers = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == 2 and any(a <= r <= b and l <= c <= rr for a,b,l,rr in boxes):
                centers.add((r,c))
    for r,c in centers:
        for y in range(max(0,r-1), min(h,r+2)):
            for x in range(max(0,c-1), min(w,c+2)):
                if g[y][x] != 2:
                    g[y][x] = 1
    return g
